//! display/dc/hwss/dce/dce_hwseq.h + hwss/hw_sequencer_private.h (Linux
//! 6.18.55), with the `hwseq_reg`/`hwseq_shift`/`hwseq_mask` table of
//! dcn21_resource.c: the hw-sequencer register bank. One per device, held by
//! `dc->hwseq`.
//!
//! `dcn21_hwseq_create` allocates the bank, stores the register pointers and
//! sets two Renoir workarounds; the sequences that use the bank bind as
//! `funcs` with the hw sequencer. The register table is
//! machine-generated by `dcgen.py` (single mode) from `HWSEQ_DCN21_REG_LIST` /
//! `HWSEQ_DCN21_MASK_SH_LIST` — 63 scalar + 2 per-OTG PIXEL_RATE arrays.
#![allow(dead_code)]

use crate::regs::*;
use alloc::boxed::Box;

/// `struct dce_hwseq_wa` (hw_sequencer_private.h): the workaround flags. Ported
/// grow-as-reached — the create sets these two for Renoir; the rest join as the
/// hwss sequences reach them.
#[derive(Default)]
pub struct dce_hwseq_wa {
    pub DEGVIDCN21: bool,
    pub disallow_self_refresh_during_multi_plane_transition: bool,
}

/// `struct dce_hwseq` (hw_sequencer_private.h): the hw-sequencer state. `ctx` is
/// not stored (see `clock_source`); `wa_state` and the `fb_*`/`uma_top`
/// addresses join with the stages that use them.
#[derive(Default)]
pub struct dce_hwseq {
    pub regs: Option<&'static dce_hwseq_registers>,
    pub shifts: Option<&'static dce_hwseq_shift>,
    pub masks: Option<&'static dce_hwseq_mask>,
    pub wa: dce_hwseq_wa,
    pub funcs: crate::hw_sequencer::hwseq_private_funcs,
}

impl dce_hwseq {
    /// The `(regs, shift, mask)` of the REG_* helpers.
    pub fn rsm(&self) -> (&'static dce_hwseq_registers, &'static dce_hwseq_shift, &'static dce_hwseq_mask) {
        (self.regs.unwrap(), self.shifts.unwrap(), self.masks.unwrap())
    }
}

/// `dcn21_hwseq_create` (dcn21_resource.c): allocate the bank, store the
/// register pointers and set the Renoir workarounds.
pub fn dcn21_hwseq_create() -> Box<dce_hwseq> {
    let mut hws = Box::new(dce_hwseq::default());
    hws.regs = Some(&HWSEQ_REGS);
    hws.shifts = Some(&HWSEQ_SHIFT);
    hws.masks = Some(&HWSEQ_MASK);
    hws.wa.DEGVIDCN21 = true;
    hws.wa.disallow_self_refresh_during_multi_plane_transition = true;
    hws
}

